<!--
文件：web/src/modules/test-management/casework/TestCasePage.vue
说明：测试案例页面或交互组件。
用途：承载用户可见的加载、空、失败、提交和交互状态。
作者：hengguan
-->
<script setup lang="ts">
// 关键逻辑：页面只消费现有全局项目上下文；当前测试大类、项目和实体选择共同决定请求范围，前端显隐不替代服务端校验。
import { computed, onBeforeUnmount, onMounted, reactive, ref, shallowRef, watch } from 'vue'
import { CircleClose, Delete, Edit, Folder, FolderOpened, Plus, Refresh, Search, Setting, Upload, Rank } from '@element-plus/icons-vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { useRoute } from 'vue-router'
import { Editor as WangEditor, Toolbar } from '@wangeditor/editor-for-vue'
import '@wangeditor/editor/dist/css/style.css'
import UiDataTable from '../../../components/ui/UiDataTable.vue'
import UiEmptyState from '../../../components/ui/UiEmptyState.vue'
import UiPageHeader from '../../../components/ui/UiPageHeader.vue'
import TestManagementFormDialog from '../components/TestManagementFormDialog.vue'
import { useAuthStore } from '../../../stores/auth'
import { useProjectContextStore } from '../../../stores/project-context'
import { getAttachmentDownload, uploadAttachment } from '../../../api/attachments'
import { deleteTestCase, deleteTestCaseDirectory, downloadTestCaseFile, getTestCase, getTestCaseTree, importTestCases, listConfigurationUsers, listTestCaseScopes, listTestDictionaries, listTestDictionaryOptions, listTestProjects, listTestCases, moveTestCases, previewTestCaseBatch, previewTestCaseCode, previewTestCaseImport, saveTestCase, saveTestCaseDirectory, setTestCaseInvalidated, updateTestCaseBatch, type TestCase, type TestCaseFilters, type TestCaseImportPreview, type TestDictionary, type TestDictionaryOption, type TestDirectory, type TestDomain, type TestManagementTree, type TestScope, type UserDirectoryItem } from '../api'

type TreeNode = { key: string; type: 'project' | 'system' | 'directory'; id?: number; label: string; directory?: TestDirectory; children?: TreeNode[] }
type Column = { key: string; label: string; prop?: keyof TestCase; width?: number; minWidth?: number; visible: boolean }
const route = useRoute(); const auth = useAuthStore(); const context = useProjectContextStore()
const domain = computed(() => String(route.params.domain) as TestDomain)
const domainName = computed(() => ({ 'application-assembly': '应用组装测试', 'user-testing': '用户测试', 'non-functional': '非功能测试', security: '安全测试' }[domain.value] || '测试管理'))
const projects = ref<Array<{ id: number; project_code: string; project_name: string }>>([])
const projectId = computed(() => projects.value.find(item => item.project_code === context.currentRef)?.id)
const projectName = computed(() => projects.value.find(item => item.id === projectId.value)?.project_name || '当前项目')
const tree = ref<TestManagementTree>(); const scopes = ref<TestScope[]>([]); const rows = ref<TestCase[]>([]); const total = ref(0); const page = ref(1); const loading = ref(false)
const selectedSystem = ref<number>(); const selectedDirectory = ref<number>(); const keyword = ref(''); const selectedRows = ref<TestCase[]>([])
const filters = reactive({ scopeId: undefined as number | undefined, caseType: [] as string[], caseNature: [] as string[], priority: [] as string[], status: [] as string[], accountingResult: [] as string[], executionReference: '' as '' | 'REFERENCED' | 'UNREFERENCED' })
const sort = reactive({ prop: 'updated_at', order: 'descending' as 'ascending' | 'descending' })
const formDialog = ref(false); const directoryDialog = ref(false); const columnDialog = ref(false); const importDialog = ref(false); const moveDialog = ref(false); const batchDialog = ref(false); const saving = ref(false)
const editing = ref<TestCase>(); const editingDirectory = ref<TestDirectory>(); const form = reactive<Partial<TestCase> & { attachment_ids: number[] }>({ attachment_ids: [] }); const directory = reactive<Partial<TestDirectory>>({})
const content = reactive({ precondition: '', steps: '', expected: '' }); const editors = shallowRef<any[]>([]); const codePreview = ref('保存后自动生成')
const users = ref<UserDirectoryItem[]>([]); const dictionaries = ref<TestDictionary[]>([]); const options = reactive<Record<string, TestDictionaryOption[]>>({})
const importFile = ref<File>(); const importPreview = ref<TestCaseImportPreview>(); const duplicateAction = ref<'SKIP' | 'OVERWRITE'>('SKIP')
const moveTargetId = ref<number>(); const batch = reactive({ step: 0, field: 'priority', value: '', confirmed: false, confirmScopeSync: false, preview: undefined as Record<string, any> | undefined, codes: '' })
const toolbar = { toolbarKeys: ['headerSelect', '|', 'bold', 'underline', 'italic', 'color', 'bgColor', 'fontSize', '|', 'bulletedList', 'numberedList', 'justifyLeft', 'justifyCenter', '|', 'insertLink', 'insertTable', 'undo', 'redo'] }
const allColumns: Column[] = [
  { key: 'case_code', label: '案例编号', prop: 'case_code', minWidth: 148, visible: true }, { key: 'case_name', label: '案例名称', prop: 'case_name', minWidth: 180, visible: true },
  { key: 'scope_code', label: '所属范围序号', prop: 'scope_code', minWidth: 138, visible: true }, { key: 'scope_name', label: '所属范围', prop: 'scope_name', minWidth: 144, visible: false },
  { key: 'physical_system_name', label: '所属系统', prop: 'physical_system_name', minWidth: 116, visible: true }, { key: 'directory_name', label: '所属目录', prop: 'directory_name', minWidth: 116, visible: true },
  { key: 'case_type', label: '案例类型', prop: 'case_type', minWidth: 96, visible: true }, { key: 'case_nature', label: '案例性质', prop: 'case_nature', minWidth: 96, visible: true },
  { key: 'priority', label: '案例优先级', prop: 'priority', minWidth: 104, visible: true }, { key: 'status', label: '状态', prop: 'status', width: 90, visible: true },
  { key: 'accounting_result', label: '核算核对结果', prop: 'accounting_result', minWidth: 112, visible: true }, { key: 'accounting_confirmer_name', label: '核对确认人', prop: 'accounting_confirmer_name', minWidth: 100, visible: false },
  { key: 'created_by_name', label: '设计人', prop: 'created_by_name', minWidth: 90, visible: true }, { key: 'updated_by_name', label: '更新人', prop: 'updated_by_name', minWidth: 90, visible: false },
  { key: 'updated_at', label: '更新时间', prop: 'updated_at', minWidth: 132, visible: true }, { key: 'attachment_count', label: '附件数', prop: 'attachment_count', width: 72, visible: false }
]
const columns = ref<Column[]>(allColumns.map(item => ({ ...item })))
const systems = computed(() => tree.value?.systems || []); const directories = computed(() => tree.value?.directories || []); const activeColumns = computed(() => columns.value.filter(item => item.visible))
const selectedTreeKey = computed(() => selectedDirectory.value ? 'directory:' + selectedDirectory.value : selectedSystem.value ? 'system:' + selectedSystem.value : 'project')
const columnKey = computed(() => 'tm-case-columns:' + (auth.user?.id || 'anonymous') + ':' + domain.value + ':' + (projectId.value || 0))
const can = (action?: string) => auth.hasPermission('test-management:' + domain.value + ':cases' + (action ? ':' + action : ''))
const availableDirectories = computed(() => directories.value.filter(item => !form.physical_subsystem_id || item.physical_subsystem_id === form.physical_subsystem_id))
const dictionaryOptions = (code: string) => options[code] || []
const currentSystemName = computed(() => { const item = systems.value.find(value => value.id === form.physical_subsystem_id); return item ? item.short_name || item.name : '-' })
function children(systemId: number, parentId?: number): TreeNode[] { return directories.value.filter(item => item.physical_subsystem_id === systemId && (item.parent_id || undefined) === parentId).map(item => ({ key: 'directory:' + item.id, type: 'directory', id: item.id, label: item.directory_name, directory: item, children: children(systemId, item.id) })) }
const treeData = computed<TreeNode[]>(() => [{ key: 'project', type: 'project', label: projectName.value, children: systems.value.map(item => ({ key: 'system:' + item.id, type: 'system', id: item.id, label: item.short_name || item.name, children: children(item.id) })) }])
function message(cause: any, fallback: string) { ElMessage.error(cause?.response?.data?.message || fallback) }
function statusName(value?: string) { return ({ SUCCESS: '成功', FAILED: '失败', RUNNING: '执行中', INVALID: '无效', UNEXECUTED: '未执行' } as Record<string, string>)[value || ''] || '未执行' }
function statusType(value?: string) { return ({ SUCCESS: 'success', FAILED: 'danger', RUNNING: 'warning', INVALID: 'info', UNEXECUTED: 'info' } as Record<string, any>)[value || 'UNEXECUTED'] }
function accountingName(value?: string) { return ({ UNEXECUTED: '未执行', PENDING_REVIEW: '待核对', SUCCESS: '一致', FAILED: '不一致', INVALID: '不适用' } as Record<string, string>)[value || ''] || '-' }
function optionName(dictionary: string, value?: string) { return dictionaryOptions(dictionary).find(item => item.option_code === value)?.option_name || value || '-' }
function formatTime(value?: unknown) { return value ? String(value).slice(5, 16).replace('T', ' ') : '-' }
function restoreColumns() { try { const saved = JSON.parse(localStorage.getItem(columnKey.value) || '[]') as Column[]; columns.value = saved.length ? saved.map(item => ({ ...allColumns.find(base => base.key === item.key), ...item })).filter(item => item.key) as Column[] : allColumns.map(item => ({ ...item })) } catch { columns.value = allColumns.map(item => ({ ...item })) } }
function saveColumns() { localStorage.setItem(columnKey.value, JSON.stringify(columns.value)) }
async function loadDictionaries() { if (!projectId.value) return; dictionaries.value = (await listTestDictionaries(domain.value, { projectId: projectId.value, page: 1, size: 100 })).data.data.records || []; await Promise.all(['case_type', 'case_nature', 'case_priority'].map(async code => { const item = dictionaries.value.find(value => value.dictionary_code === code); options[code] = item ? ((await listTestDictionaryOptions(domain.value, { projectId: projectId.value!, dictionaryId: item.id, page: 1, size: 100 })).data.data.records || []) : [] })) }
async function load() { if (!projectId.value) return; loading.value = true; try { const params: TestCaseFilters = { projectId: projectId.value, page: page.value, size: 20, physicalSubsystemId: selectedSystem.value, directoryId: selectedDirectory.value, scopeId: filters.scopeId, keyword: keyword.value || undefined, caseType: filters.caseType, caseNature: filters.caseNature, priority: filters.priority, status: filters.status, accountingResult: filters.accountingResult, executionReference: filters.executionReference || undefined, sortBy: sort.prop, sortOrder: sort.order }; const [treeResult, scopeResult, listResult] = await Promise.all([getTestCaseTree(domain.value, projectId.value), listTestCaseScopes(domain.value, projectId.value, selectedSystem.value), listTestCases(domain.value, params)]); tree.value = treeResult.data.data; scopes.value = scopeResult.data.data || []; rows.value = listResult.data.data.records || []; total.value = listResult.data.data.total || 0 } catch (cause) { message(cause, '测试案例加载失败') } finally { loading.value = false } }
function selectTree(node: TreeNode) { selectedSystem.value = node.type === 'system' ? node.id : node.type === 'directory' ? node.directory?.physical_subsystem_id : undefined; selectedDirectory.value = node.type === 'directory' ? node.id : undefined; filters.scopeId = undefined; page.value = 1; void load() }
function resetFilters() { keyword.value = ''; Object.assign(filters, { scopeId: undefined, caseType: [], caseNature: [], priority: [], status: [], accountingResult: [], executionReference: '' }); page.value = 1; void load() }
function resetForm() { Object.keys(form).forEach(key => delete (form as any)[key]); Object.assign(form, { physical_subsystem_id: selectedSystem.value, directory_id: selectedDirectory.value, attachment_ids: [] }); Object.assign(content, { precondition: '', steps: '', expected: '' }); codePreview.value = '保存后自动生成' }
async function openCase(item?: TestCase) { if (!item && !selectedSystem.value) { ElMessage.warning('请先在左侧选择所属系统或所属目录'); return }; editing.value = item; resetForm(); if (item) { const detail = (await getTestCase(domain.value, projectId.value!, item.id)).data.data; Object.assign(form, { ...detail, attachment_ids: detail.attachments?.map(file => file.id) || [] }); Object.assign(content, { precondition: detail.precondition_html || '', steps: detail.steps_html || '', expected: detail.expected_result_html || '' }); codePreview.value = detail.case_code } formDialog.value = true }
async function refreshCode() { if (!projectId.value || !form.scope_id) return; const scope = scopes.value.find(item => item.id === form.scope_id); form.physical_subsystem_id = scope?.physical_subsystem_id; if (form.directory_id && !availableDirectories.value.some(item => item.id === form.directory_id)) form.directory_id = undefined; if (editing.value) return; try { codePreview.value = (await previewTestCaseCode(domain.value, projectId.value, form.scope_id)).data.data.case_code } catch (cause) { message(cause, '案例编号预览失败') } }
async function submitCase() { if (!projectId.value || !form.scope_id || !form.directory_id || !form.case_name || !content.steps || !content.expected) { ElMessage.warning('请填写案例名称、所属范围、所属目录、操作步骤和预期结果'); return }; saving.value = true; try { let response = await saveTestCase(domain.value, projectId.value, { ...form, precondition_html: content.precondition, steps_html: content.steps, expected_result_html: content.expected }); if (response.data.data.confirmation_required) { await ElMessageBox.confirm('变更所属范围会同步重算案例编号前缀；执行记录、缺陷编号和快照不受影响。是否继续？', '确认范围变更', { type: 'warning' }); response = await saveTestCase(domain.value, projectId.value, { ...form, precondition_html: content.precondition, steps_html: content.steps, expected_result_html: content.expected, confirm_scope_sync: true } as any) } formDialog.value = false; ElMessage.success(editing.value ? '案例已更新' : '案例已创建'); await load() } catch (cause: any) { if (cause !== 'cancel' && cause !== 'close') message(cause, '案例保存失败') } finally { saving.value = false } }
function openDirectory(item?: TestDirectory, child = false) { editingDirectory.value = item; Object.keys(directory).forEach(key => delete (directory as any)[key]); Object.assign(directory, item && !child ? { ...item } : { physical_subsystem_id: item?.physical_subsystem_id || selectedSystem.value, parent_id: child ? item?.id : selectedDirectory.value, sort_no: 0 }); directoryDialog.value = true }
async function submitDirectory() { if (!projectId.value || !directory.physical_subsystem_id || !directory.directory_name) { ElMessage.warning('请选择参测系统并填写目录名称'); return }; try { await saveTestCaseDirectory(domain.value, projectId.value, directory); directoryDialog.value = false; ElMessage.success(editingDirectory.value ? '目录已更新' : '目录已创建'); await load() } catch (cause) { message(cause, '目录保存失败') } }
async function removeDirectory(item: TestDirectory) { if (!projectId.value) return; try { await ElMessageBox.confirm('删除目录后，其直属案例将移交到上级目录。确认继续？', '删除案例目录', { type: 'warning' }); await deleteTestCaseDirectory(domain.value, projectId.value, item.id); ElMessage.success('目录已删除'); await load() } catch (cause: any) { if (cause !== 'cancel' && cause !== 'close') message(cause, '目录删除失败') } }
async function remove(row: TestCase) { if (!projectId.value) return; try { await ElMessageBox.confirm('确认删除案例“' + row.case_name + '”？已被执行引用的案例只能置无效。', '删除测试案例', { type: 'warning' }); await deleteTestCase(domain.value, projectId.value, row.id); ElMessage.success('案例已删除'); await load() } catch (cause: any) { if (cause !== 'cancel' && cause !== 'close') { if (cause?.response?.status === 409) void invalid(row); else message(cause, '案例删除失败') } } }
async function invalid(row: TestCase) { if (!projectId.value) return; try { const value = row.invalidated ? undefined : await ElMessageBox.prompt('无效原因', '置为无效', { inputPlaceholder: '请输入无效原因' }); await setTestCaseInvalidated(domain.value, projectId.value, row.id, !row.invalidated, value?.value || ''); await load() } catch (cause: any) { if (cause !== 'cancel' && cause !== 'close') message(cause, '状态更新失败') } }
async function upload(file: File) { if (file.size > 50 * 1024 * 1024) { ElMessage.warning('单个附件不能超过 50MB'); return }; try { const item = (await uploadAttachment(file)).data.data; form.attachment_ids.push(item.id); ElMessage.success('附件已添加') } catch (cause) { message(cause, '附件上传失败') } }
async function downloadAttachment(id: number) { try { window.open((await getAttachmentDownload(id)).data.data.downloadUrl, '_blank', 'noopener') } catch (cause) { message(cause, '附件下载失败') } }
function editorCreated(index: number, editor: any) { editors.value[index] = editor }
function sortChange(value: { prop: string; order: 'ascending' | 'descending' | null }) { sort.prop = value.prop || 'updated_at'; sort.order = value.order || 'descending'; void load() }
function selectedChange(value: TestCase[]) { selectedRows.value = value }
function openMove() { if (!selectedRows.value.length) { ElMessage.warning('请先选择需要移动的案例'); return }; moveTargetId.value = undefined; moveDialog.value = true }
async function commitMove() { if (!projectId.value || !moveTargetId.value) { ElMessage.warning('请选择目标目录'); return }; try { await moveTestCases(domain.value, projectId.value, selectedRows.value.map(item => item.id), moveTargetId.value); moveDialog.value = false; ElMessage.success('案例已移动'); await load() } catch (cause) { message(cause, '移动案例失败') } }
function openBatch() { Object.assign(batch, { step: 0, field: 'priority', value: '', confirmed: false, confirmScopeSync: false, preview: undefined, codes: '' }); batchDialog.value = true }
function batchSubjects() { return { ids: selectedRows.value.map(item => item.id), case_codes: batch.codes } }
async function batchPreview() { if (!projectId.value || !batch.value) { ElMessage.warning('请选择调整字段并填写目标值'); return }; if (!selectedRows.value.length && !batch.codes.trim()) { ElMessage.warning('请勾选案例或粘贴案例编号'); return }; try { batch.preview = (await previewTestCaseBatch(domain.value, projectId.value, { ...batchSubjects(), field: batch.field, value: batch.value })).data.data; batch.step = 3 } catch (cause) { message(cause, '批量调整预览失败') } }
async function batchCommit() { if (!projectId.value) return; saving.value = true; try { const result = await updateTestCaseBatch(domain.value, projectId.value, { ...batchSubjects(), field: batch.field, value: batch.value, confirmed: true, confirm_scope_sync: batch.confirmScopeSync }); if (result.data.data.confirmation_required) { batch.step = 3; batch.confirmScopeSync = true; return } batchDialog.value = false; ElMessage.success('已批量调整 ' + (result.data.data.updated || 0) + ' 条案例'); await load() } catch (cause) { message(cause, '批量调整失败') } finally { saving.value = false } }
async function download(path: '/template' | '/export') { if (!projectId.value) return; try { await downloadTestCaseFile(domain.value, path, path === '/template' ? {} : { projectId: projectId.value, physicalSubsystemId: selectedSystem.value, directoryId: selectedDirectory.value, scopeId: filters.scopeId, keyword: keyword.value || undefined, caseType: filters.caseType, caseNature: filters.caseNature, priority: filters.priority, status: filters.status, accountingResult: filters.accountingResult, executionReference: filters.executionReference || undefined }, path === '/template' ? '测试案例导入模板.xlsx' : '测试案例导出.xlsx') } catch (cause) { message(cause, '文件下载失败') } }
async function selectImport(file: { raw?: File }) { if (!projectId.value || !file.raw) return; importFile.value = file.raw; importPreview.value = undefined; try { importPreview.value = (await previewTestCaseImport(domain.value, projectId.value, file.raw)).data.data } catch (cause) { message(cause, '导入预校验失败') } }
async function commitImport() { if (!projectId.value || !importFile.value || !importPreview.value?.success) return; saving.value = true; try { const result = (await importTestCases(domain.value, projectId.value, importFile.value, duplicateAction.value)).data.data; importDialog.value = false; ElMessage.success('导入完成：新增 ' + (result.created || 0) + '，覆盖 ' + (result.updated || 0) + '，跳过 ' + (result.skipped || 0)); await load() } catch (cause) { message(cause, '导入提交失败') } finally { saving.value = false } }
onBeforeUnmount(() => editors.value.forEach(editor => editor?.destroy()))
onMounted(async () => { await context.initialize(); projects.value = (await listTestProjects(domain.value)).data.data || []; users.value = (await listConfigurationUsers(domain.value)).data.data || []; restoreColumns(); await Promise.all([load(), loadDictionaries()]) })
watch([() => context.currentRef, domain], async () => { page.value = 1; selectedSystem.value = undefined; selectedDirectory.value = undefined; restoreColumns(); await Promise.all([load(), loadDictionaries()]) })
</script>

<template>
  <section class="case-page">
    <UiPageHeader eyebrow="测试管理" :title="domainName + ' · 测试案例'"><template #actions><el-button v-if="can('create')" type="primary" size="small" :icon="Plus" @click="openCase()">新建案例</el-button><el-dropdown trigger="click"><el-button size="small"><el-icon><Upload /></el-icon> 导入</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item @click="download('/template')">下载模板</el-dropdown-item><el-dropdown-item @click="importDialog = true">导入案例</el-dropdown-item><el-dropdown-item @click="download('/export')">导出当前结果</el-dropdown-item></el-dropdown-menu></template></el-dropdown><el-button v-if="can('update')" size="small" :icon="Rank" @click="openBatch">批量调整</el-button><el-tooltip content="字段设置"><el-button size="small" text circle :icon="Setting" aria-label="字段设置" @click="columnDialog = true" /></el-tooltip><el-tooltip content="刷新"><el-button size="small" text circle :icon="Refresh" aria-label="刷新案例" @click="load" /></el-tooltip></template></UiPageHeader>
    <UiEmptyState v-if="!projectId" title="请先选择项目" description="请使用顶部全局项目选择器后查看测试案例。" />
    <section v-else class="case-workspace" v-loading="loading"><aside class="case-tree"><header><span>案例目录</span><el-tooltip v-if="can('create')" content="新建根目录"><el-button link :icon="Plus" aria-label="新建案例目录" @click="openDirectory()" /></el-tooltip></header><el-tree :data="treeData" node-key="key" :current-node-key="selectedTreeKey" default-expand-all highlight-current :expand-on-click-node="false" @node-click="selectTree"><template #default="{ data }"><span class="case-tree-node"><el-icon><FolderOpened v-if="data.type === 'project'" /><Folder v-else /></el-icon><span class="case-tree-label">{{ data.label }}</span><span v-if="data.type === 'directory' && can('update')" class="tree-actions"><el-button link :icon="Plus" aria-label="新建子目录" @click.stop="openDirectory(data.directory, true)" /><el-button link :icon="Edit" aria-label="编辑目录" @click.stop="openDirectory(data.directory)" /><el-button v-if="can('delete')" link type="danger" :icon="Delete" aria-label="删除目录" @click.stop="removeDirectory(data.directory)" /></span></span></template></el-tree></aside>
      <main class="case-content"><div class="case-toolbar"><el-input v-model="keyword" clearable size="small" placeholder="案例编号、名称、范围" @keyup.enter="page = 1; load()"><template #prefix><Search /></template></el-input><el-select v-model="filters.scopeId" clearable filterable size="small" placeholder="所属范围"><el-option v-for="item in scopes" :key="item.id" :label="item.scope_code + ' · ' + item.scope_name" :value="item.id" /></el-select><el-select v-model="filters.caseType" multiple collapse-tags size="small" clearable placeholder="案例类型"><el-option v-for="item in dictionaryOptions('case_type')" :key="item.id" :label="item.option_name" :value="item.option_code" /></el-select><el-select v-model="filters.caseNature" multiple collapse-tags size="small" clearable placeholder="案例性质"><el-option v-for="item in dictionaryOptions('case_nature')" :key="item.id" :label="item.option_name" :value="item.option_code" /></el-select><el-select v-model="filters.priority" multiple collapse-tags size="small" clearable placeholder="优先级"><el-option v-for="item in dictionaryOptions('case_priority')" :key="item.id" :label="item.option_name" :value="item.option_code" /></el-select><el-select v-model="filters.status" multiple collapse-tags size="small" clearable placeholder="状态"><el-option v-for="item in ['SUCCESS','FAILED','RUNNING','INVALID','UNEXECUTED']" :key="item" :label="statusName(item)" :value="item" /></el-select><el-select v-model="filters.accountingResult" multiple collapse-tags size="small" clearable placeholder="核算结果"><el-option v-for="item in ['UNEXECUTED','PENDING_REVIEW','SUCCESS','FAILED','INVALID']" :key="item" :label="accountingName(item)" :value="item" /></el-select><el-button size="small" :icon="Search" @click="page = 1; load()">查询</el-button><el-button size="small" text @click="resetFilters">重置</el-button></div><div class="case-result-bar"><span>状态取最新执行结果；执行模块尚未接入时显示未执行。无效状态优先展示。</span><el-button size="small" text :disabled="!selectedRows.length" @click="openMove">移动目录</el-button></div>
        <UiDataTable :data="rows" :loading="loading" row-key="id" border class="case-table" @sort-change="sortChange" @selection-change="selectedChange"><el-table-column type="selection" width="38" :resizable="false" /><el-table-column v-for="column in activeColumns" :key="column.key" :label="column.label" :prop="column.prop as string" :width="column.width" :min-width="column.minWidth" :sortable="column.key === 'status' ? false : 'custom'" show-overflow-tooltip resizable><template v-if="column.key === 'status'" #default="{ row }"><el-tag :type="statusType(row.status)" size="small">{{ statusName(row.status) }}</el-tag></template><template v-else-if="column.key === 'case_type'" #default="{ row }">{{ optionName('case_type', row.case_type) }}</template><template v-else-if="column.key === 'case_nature'" #default="{ row }">{{ optionName('case_nature', row.case_nature) }}</template><template v-else-if="column.key === 'priority'" #default="{ row }">{{ optionName('case_priority', row.priority) }}</template><template v-else-if="column.key === 'accounting_result'" #default="{ row }">{{ accountingName(row.accounting_result) }}</template><template v-else-if="column.key === 'updated_at'" #default="{ row }">{{ formatTime(row.updated_at) }}</template></el-table-column><el-table-column label="操作" width="72" fixed="right" align="center" header-align="center" :resizable="false"><template #default="{ row }"><div class="case-actions"><el-tooltip v-if="can('update')" content="编辑"><el-button link :icon="Edit" aria-label="编辑案例" @click="openCase(row)" /></el-tooltip><el-tooltip v-if="can('update')" :content="row.invalidated ? '恢复有效' : '置无效'"><el-button link aria-label="切换案例有效状态" @click="invalid(row)"><el-icon><CircleClose /></el-icon></el-button></el-tooltip><el-tooltip v-if="can('delete')" content="删除"><el-button link type="danger" :icon="Delete" aria-label="删除案例" @click="remove(row)" /></el-tooltip></div></template></el-table-column><template #footer><el-pagination v-model:current-page="p