    <TestManagementFormDialog v-model="formDialog" :title="editing ? '编辑测试案例' : '新建测试案例'" width="min(980px, calc(100vw - 24px))" :loading="saving" @submit="submitCase"><el-form label-width="104px"><div class="form-grid"><el-form-item label="案例编号"><el-input :model-value="editing?.case_code || codePreview" disabled /></el-form-item><el-form-item label="案例名称" required><el-input v-model="form.case_name" maxlength="200" /></el-form-item><el-form-item label="所属范围" required><el-select v-model="form.scope_id" filterable style="width:100%" @change="refreshCode"><el-option v-for="item in scopes" :key="item.id" :label="item.scope_code + ' · ' + item.scope_name" :value="item.id" /></el-select></el-form-item><el-form-item label="所属系统"><el-input :model-value="currentSystemName" disabled /></el-form-item><el-form-item label="所属目录" required><el-select v-model="form.directory_id" filterable style="width:100%"><el-option v-for="item in availableDirectories" :key="item.id" :label="item.directory_name" :value="item.id" /></el-select></el-form-item><el-form-item label="案例类型" required><el-select v-model="form.case_type" style="width:100%"><el-option v-for="item in dictionaryOptions('case_type')" :key="item.id" :label="item.option_name" :value="item.option_code" /></el-select></el-form-item><el-form-item label="案例性质" required><el-select v-model="form.case_nature" style="width:100%"><el-option v-for="item in dictionaryOptions('case_nature')" :key="item.id" :label="item.option_name" :value="item.option_code" /></el-select></el-form-item><el-form-item label="案例优先级" required><el-select v-model="form.priority" style="width:100%"><el-option v-for="item in dictionaryOptions('case_priority')" :key="item.id" :label="item.option_name" :value="item.option_code" /></el-select></el-form-item><el-form-item label="核算核对结果"><el-select v-model="form.accounting_result" clearable style="width:100%"><el-option v-for="item in ['UNEXECUTED','PENDING_REVIEW','SUCCESS','FAILED','INVALID']" :key="item" :label="accountingName(item)" :value="item" /></el-select></el-form-item><el-form-item label="核对确认人"><el-select v-model="form.accounting_confirmed_by" clearable filterable style="width:100%"><el-option v-for="item in users" :key="item.id" :label="item.displayName || item.username" :value="item.id" /></el-select></el-form-item><el-form-item label="案例状态"><el-input :model-value="editing ? statusName(editing.status) : '未执行（保存后由执行结果实时计算）'" disabled /></el-form-item></div><el-form-item label="前置条件"><div class="rich"><Toolbar :editor="editors[0]" :default-config="toolbar" mode="default" /><WangEditor v-model="content.precondition" :default-config="{ placeholder: '支持粘贴 Word 内容、颜色、表格等富文本' }" mode="default" @on-created="(editor: any) => editorCreated(0, editor)" /></div></el-form-item><el-form-item label="操作步骤" required><div class="rich"><Toolbar :editor="editors[1]" :default-config="toolbar" mode="default" /><WangEditor v-model="content.steps" :default-config="{ placeholder: '请输入操作步骤' }" mode="default" @on-created="(editor: any) => editorCreated(1, editor)" /></div></el-form-item><el-form-item label="预期结果" required><div class="rich"><Toolbar :editor="editors[2]" :default-config="toolbar" mode="default" /><WangEditor v-model="content.expected" :default-config="{ placeholder: '请输入预期结果' }" mode="default" @on-created="(editor: any) => editorCreated(2, editor)" /></div></el-form-item><el-form-item label="备注"><el-input v-model="form.remark" type="textarea" :rows="3" maxlength="500" show-word-limit /></el-form-item><el-form-item label="附件"><el-upload :show-file-list="false" :auto-upload="false" @change="(file: any) => upload(file.raw)"><el-button size="small">添加附件</el-button></el-upload><el-space wrap class="files"><el-tag v-for="id in form.attachment_ids" :key="id" closable @close="form.attachment_ids = form.attachment_ids.filter(item => item !== id)" @click="downloadAttachment(id)">附件 #{{ id }}</el-tag></el-space></el-form-item></el-form></TestManagementFormDialog>
    <el-dialog v-model="directoryDialog" :title="editingDirectory ? '编辑案例目录' : '新建案例目录'" width="min(480px, calc(100vw - 24px))" align-center><el-form label-width="86px"><el-form-item label="参测系统" required><el-select v-model="directory.physical_subsystem_id" style="width:100%" :disabled="Boolean(editingDirectory)"><el-option v-for="item in systems" :key="item.id" :label="item.short_name || item.name" :value="item.id" /></el-select></el-form-item><el-form-item label="上级目录"><el-select v-model="directory.parent_id" clearable style="width:100%"><el-option v-for="item in directories.filter(value => value.physical_subsystem_id === directory.physical_subsystem_id && value.id !== directory.id)" :key="item.id" :label="item.directory_name" :value="item.id" /></el-select></el-form-item><el-form-item label="目录名称" required><el-input v-model="directory.directory_name" maxlength="100" /></el-form-item><el-form-item label="排序"><el-input-number v-model="directory.sort_no" :min="0" /></el-form-item></el-form><template #footer><el-button @click="directoryDialog = false">取消</el-button><el-button type="primary" @click="submitDirectory">保存</el-button></template></el-dialog>
    <el-dialog v-model="columnDialog" title="字段设置" width="min(460px, calc(100vw - 24px))" align-center><p class="dialog-tip">勾选显示字段；列宽可直接在列表标题处拖动调整，设置按当前用户、项目和测试大类保存。</p><div class="column-settings"><el-checkbox v-for="column in columns" :key="column.key" v-model="column.visible">{{ column.label }}</el-checkbox></div><template #footer><el-button @click="columns = allColumns.map(item => ({ ...item }))">恢复默认</el-button><el-button @click="columnDialog = false">取消</el-button><el-button type="primary" @click="saveColumns(); columnDialog = false">保存设置</el-button></template></el-dialog>
    <el-dialog v-model="moveDialog" title="移动测试案例" width="min(460px, calc(100vw - 24px))" align-center><el-alert :title="'将 ' + selectedRows.length + ' 条案例移动到目标目录，案例编号不会改变。'" type="info" :closable="false" show-icon /><el-form class="dialog-form" label-width="86px"><el-form-item label="目标目录" required><el-select v-model="moveTargetId" filterable style="width:100%"><el-option v-for="item in directories" :key="item.id" :label="item.directory_name" :value="item.id" /></el-select></el-form-item></el-form><template #footer><el-button @click="moveDialog = false">取消</el-button><el-button type="primary" @click="commitMove">确认移动</el-button></template></el-dialog>
    <el-dialog v-model="batchDialog" title="批量调整测试案例" width="min(760px, calc(100vw - 24px))" align-center><el-steps :active="batch.step" simple><el-step title="选择对象" /><el-step title="选择字段" /><el-step title="填写新值" /><el-step title="预览确认" /><el-step title="完成" /></el-steps><section class="batch-body"><template v-if="batch.step === 0"><p>已从列表勾选 <strong>{{ selectedRows.length }}</strong> 条案例；也可粘贴案例编号（每行一个或以逗号分隔）。</p><el-input v-model="batch.codes" type="textarea" :rows="4" placeholder="可选：粘贴案例编号，例如 W10011-0001-0001" /><div class="dialog-actions"><el-button type="primary" :disabled="!selectedRows.length && !batch.codes.trim()" @click="batch.step = 1">下一步</el-button></div></template><template v-else-if="batch.step === 1"><el-select v-model="batch.field" style="width:100%"><el-option label="案例类型" value="case_type" /><el-option label="案例性质" value="case_nature" /><el-option label="案例优先级" value="priority" /><el-option label="核算核对结果" value="accounting_result" /><el-option label="所属范围" value="scope_id" /><el-option label="所属目录" value="directory_id" /><el-option label="案例名称" value="case_name" /><el-option label="前置条件" value="precondition_html" /><el-option label="操作步骤" value="steps_html" /><el-option label="预期结果" value="expected_result_html" /><el-option label="备注" value="remark" /></el-select><div class="dialog-actions"><el-button @click="batch.step = 0">上一步</el-button><el-button type="primary" @click="batch.step = 2">下一步</el-button></div></template><template v-else-if="batch.step === 2"><el-select v-if="batch.field === 'scope_id'" v-model="batch.value" filterable style="width:100%"><el-option v-for="item in scopes" :key="item.id" :label="item.scope_code + ' · ' + item.scope_name" :value="String(item.id)" /></el-select><el-select v-else-if="batch.field === 'directory_id'" v-model="batch.value" filterable style="width:100%"><el-option v-for="item in directories" :key="item.id" :label="item.directory_name" :value="String(item.id)" /></el-select><el-select v-else-if="batch.field === 'case_type' || batch.field === 'case_nature' || batch.field === 'priority'" v-model="batch.value" style="width:100%"><el-option v-for="item in dictionaryOptions(batch.field === 'case_type' ? 'case_type' : batch.field === 'case_nature' ? 'case_nature' : 'case_priority')" :key="item.id" :label="item.option_name" :value="item.option_code" /></el-select><el-select v-else-if="batch.field === 'accounting_result'" v-model="batch.value" style="width:100%"><el-option v-for="item in ['UNEXECUTED','PENDING_REVIEW','SUCCESS','FAILED','INVALID']" :key="item" :label="accountingName(item)" :value="item" /></el-select><el-input v-else v-model="batch.value" type="textarea" :rows="3" /><div class="dialog-actions"><el-button @click="batch.step = 1">上一步</el-button><el-button type="primary" @click="batchPreview">生成预览</el-button></div></template><template v-else><el-alert v-if="batch.preview?.requires_scope_sync" title="变更范围将同步重算案例编号前缀。执行记录、缺陷编号和快照不受影响。" type="warning" :closable="false" show-icon /><p>影响 {{ batch.preview?.affected_case_count || 0 }} 条案例，以下展示前 100 条。</p><el-table :data="batch.preview?.records || []" size="small" max-height="260"><el-table-column prop="case_code" label="案例编号" width="150" /><el-table-column prop="case_name" label="案例名称" /><el-table-column prop="old_value" label="原值" /><el-table-column prop="new_value" label="新值" /></el-table><el-checkbox v-if="batch.preview?.requires_scope_sync" v-model="batch.confirmScopeSync">我确认同步更新案例编号前缀</el-checkbox><div class="dialog-actions"><el-button @click="batch.step = 2">返回修改</el-button><el-button type="primary" :loading="saving" @click="batchCommit">确认执行</el-button></div></template></section></el-dialog>
    <el-dialog v-model="importDialog" title="批量导入测试案例" width="min(760px, calc(100vw - 24px))" align-center destroy-on-close><el-alert title="仅支持 XLSX，单文件不超过 50MB。导入前必须通过预校验；存在任何错误行时不会写入数据。" type="info" :closable="false" show-icon /><el-upload class="case-import" drag :auto-upload="false" accept=".xlsx" :limit="1" :on-change="selectImport" :on-remove="() => { importFile = undefined; importPreview = undefined }"><el-icon class="el-icon--upload"><Upload /></el-icon><div class="el-upload__text">拖入 XLSX 文件，或 <em>点击选择</em></div></el-upload><template v-if="importPreview"><div class="import-summary"><span>总计 {{ importPreview.total }}</span><span>通过 {{ importPreview.valid }}</span><span>失败 {{ importPreview.failed }}</span><span>重复 {{ importPreview.duplicate }}</span><span>待建目录 {{ importPreview.directories }}</span></div><el-radio-group v-if="importPreview.duplicate" v-model="duplicateAction"><el-radio value="SKIP">重复编号跳过</el-radio><el-radio value="OVERWRITE">覆盖非空字段</el-radio></el-radio-group><el-table v-if="importPreview.errors.length" :data="importPreview.errors" size="small" max-height="180"><el-table-column prop="row_number" label="行号" width="80" /><el-table-column prop="message" label="错误说明" /></el-table></template><template #footer><el-button @click="importDialog = false">取消</el-button><el-button type="primary" :disabled="!importPreview?.success" :loading="saving" @click="commitImport">确认导入</el-button></template></el-dialog>
